function cRes(){return `<h1>Published Results</h1><p class="mu" style="margin:4px 0 18px">You can only see your own results.</p><div class="card row sp"><div><span class="mu sm">DB-204-MID</span><h3>Database Internals & Indexing</h3><b>43 / 50 (86%)</b></div><div class="row"><span class="pill ok">Passed</span><button class="btn g s" onclick="go('report')">Report & PDF</button><button class="btn g s" onclick="modal(dsp())">Raise dispute</button></div></div>`}
function dsp(){return `<h2>Raise a dispute</h2><p class="mu sm" style="margin:4px 0 12px">Examiners review every dispute. The original score stays unchanged until a decision is recorded with a reason.</p><div class="col"><label>Reason<select id="dr"><option>Grading error</option><option>Ambiguous question</option><option>Technical incident</option></select></label><label>Details<textarea id="dd" rows="3"></textarea></label><span class="err" id="de"></span><button class="btn" onclick="if($('#dd').value.trim().length<10){$('#de').textContent='Add at least 10 characters of detail.';return}disputes.unshift({id:Date.now(),n:S.user.name,ex:'DB-204-MID',why:$('#dr').value+': '+$('#dd').value,st:'Open'});modal();toast('Dispute submitted')">Submit dispute</button></div>`}
function report(){return `<div style="max-width:760px;margin:auto" class="col"><a href="#" class="mu noprint" onclick="go('dash');return false">← Back</a><div class="card col"><div class="row sp"><div><span class="pill in">Official result report</span><h1 style="margin-top:8px">Database Internals & Indexing</h1><p class="mu">DB-204-MID · ${S.user.name} (${S.user.reg||""})</p></div><div class="qr"></div></div>
<div class="grid g3"><div class="stat ok"><b>43 / 50</b>Score (86%)</div><div class="stat"><b>Passed</b>Pass mark 25</div><div class="stat"><b>Top 12%</b>Cohort position</div></div><table><tr><th>Section</th><th>Marks</th></tr><tr><td>Objective (auto-graded)</td><td>28 / 30</td></tr><tr><td>Written (manually graded)</td><td>15 / 20</td></tr></table><p class="sm">Verification ID <span class="verify">VR-7F3K-92QX</span><br><span class="mu">Verify at the Verify Report page. Only initials, exam and score band are shown.</span></p><button class="btn noprint" onclick="window.print()">Download PDF</button></div></div>`}
function verifyV(){return `<div style="max-width:560px;margin:auto" class="card col"><h1>Verify a report</h1><p class="mu">Enter the verification ID printed on the report.</p><label>Verification ID<input id="vi" placeholder="VR-XXXX-XXXX"></label><button class="btn" onclick="vf()">Verify</button><div id="vr"></div></div>`}
function vf(){const v=$("#vi").value.trim().toUpperCase();$("#vr").innerHTML=v=="VR-7F3K-92QX"?`<div class="card" style="background:var(--okb);color:var(--ok)"><b>✔ Authentic report</b><p class="sm">Exam: DB-204-MID · Candidate: A. T. · Result: Passed · Score band: 80–90%. Issued Nov 20, 2026.</p></div>`:`<div class="card" style="background:var(--erb);color:var(--er)"><b>✖ No report found</b><p class="sm">Check the ID and try again. Try VR-7F3K-92QX.</p></div>`}
